package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain returns a way to order the given dominoes so that they form a
// correct closed domino chain, or false if no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	chain := make([]Domino, len(input))
	used := make([]bool, len(input))

	if chain := search(input, used, chain, 0, -1); chain != nil {
		return chain, true
	}
	return nil, false
}

// search tries to build a chain of length `pos` where the last placed domino
// ends with value `end`. A value of -1 for `end` means the chain is empty.
func search(input []Domino, used []bool, chain []Domino, pos, end int) []Domino {
	if pos == len(input) {
		// The chain is complete; it is closed only if the last value matches
		// the first value.
		if chain[0][0] == chain[len(chain)-1][1] {
			return chain
		}
		return nil
	}

	for i := range input {
		if used[i] {
			continue
		}
		a, b := input[i][0], input[i][1]
		for _, orientation := range [][2]int{{a, b}, {b, a}} {
			if pos == 0 || orientation[0] == end {
				used[i] = true
				chain[pos] = Domino(orientation)
				if result := search(input, used, chain, pos+1, orientation[1]); result != nil {
					return result
				}
				chain[pos] = Domino{}
				used[i] = false
			}
		}
	}
	return nil
}
