package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain returns a way to order the given dominoes so that they form a
// correct closed domino chain: adjacent halves match, and the two open ends
// (first and last halves) match each other. Each domino may be used once and
// may be flipped. It returns false if no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	// A closed chain visiting every stone requires that every non-isolated
	// value appears an even number of times and that the stones form a single
	// connected component. This is a necessary (not sufficient) condition, so
	// failing it lets us bail out quickly.
	if !canChain(input) {
		return nil, false
	}

	chain := make([]Domino, len(input))
	used := make([]bool, len(input))

	if found := search(input, used, chain, 0, -1); found != nil {
		return found, true
	}
	return nil, false
}

// canChain reports whether the input satisfies the necessary conditions for a
// closed chain: even degree at every value and a single connected component.
func canChain(input []Domino) bool {
	degree := make(map[int]int)
	adj := make(map[int]map[int]bool)
	for _, d := range input {
		degree[d[0]]++
		degree[d[1]]++
		if adj[d[0]] == nil {
			adj[d[0]] = make(map[int]bool)
		}
		if adj[d[1]] == nil {
			adj[d[1]] = make(map[int]bool)
		}
		adj[d[0]][d[1]] = true
		adj[d[1]][d[0]] = true
	}

	for v := range degree {
		if degree[v]%2 != 0 {
			return false
		}
	}

	// Walk the component reachable from the first stone's value.
	start := input[0][0]
	seen := make(map[int]bool)
	stack := []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if seen[v] {
			continue
		}
		seen[v] = true
		for w := range adj[v] {
			if !seen[w] {
				stack = append(stack, w)
			}
		}
	}

	for v := range degree {
		if !seen[v] {
			return false
		}
	}
	return true
}

// search tries to build a chain of length `pos` whose last placed half is
// `end`. A value of -1 for `end` means the chain is still empty. It returns a
// completed closed chain or nil if none can be built from this state.
func search(input []Domino, used []bool, chain []Domino, pos, end int) []Domino {
	if pos == len(input) {
		// The chain is complete; it is closed only if the last half matches
		// the first half.
		if chain[0][0] == chain[len(chain)-1][1] {
			return chain
		}
		return nil
	}

	for i := range input {
		if used[i] {
			continue
		}
		a, b := input[i][0], input[i][1]
		for _, orientation := range [][2]int{{a, b}, {b, a}} {
			if pos == 0 || orientation[0] == end {
				used[i] = true
				chain[pos] = Domino(orientation)
				if result := search(input, used, chain, pos+1, orientation[1]); result != nil {
					return result
				}
				chain[pos] = Domino{}
				used[i] = false
			}
		}
	}
	return nil
}
